/**
 * Phase 3-4 quiz bank (exam-level, B2+ to C1). Original content.
 * IDs: "q34-<topic>-NNNN", assigned by position within each topic. APPEND ONLY: never reorder or delete.
 */
import { mcq, gap, tfng, heading } from './helpers';
import type { PhaseId } from '../data/types';
import type { Cefr, QuizItem } from './types';

type Raw = ReturnType<typeof mcq> | ReturnType<typeof gap> | ReturnType<typeof tfng> | ReturnType<typeof heading>;

function withIds34(raws: Raw[]): QuizItem[] {
  const n: Record<string, number> = {};
  return raws.map((r) => {
    n[r.topic] = (n[r.topic] ?? 0) + 1;
    return { ...r, id: `q34-${r.topic}-${String(n[r.topic]).padStart(4, '0')}` } as QuizItem;
  });
}

/**
 * Heading helper. Arguments: phase, cefr, paragraph, correct heading, distractors, k, explanation.
 * The correct heading is inserted at position k (0-based, clamped to the option count), and answerIndex is k.
 * Explanations must quote option text and never refer to an option by number or letter,
 * because the app shuffles option order at display time.
 */
function hd(phase: PhaseId, cefr: Cefr, paragraph: string, correct: string, distractors: string[], k: number, explanation: string): Raw {
  const pos = Math.max(0, Math.min(k, distractors.length));
  const options = [...distractors];
  options.splice(pos, 0, correct);
  return heading('reading-headings', phase, cefr, paragraph, options, pos, explanation);
}

const TF = 'reading-tfng' as const;
